begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into ingest.telegram_sales_channels values('11111111-1111-1111-1111-111111111111',-700123);
create temporary table mention_fixture as
select (api.accept_intake('11111111-1111-1111-1111-111111111111','meta','facebook','mention-fixture','mention-fixture',
 '{}'::jsonb,jsonb_build_object('name','Synthetic enquiry','phone','+601199988877'))->>'lead_id')::uuid id;
update sales.leads set owner_id='aaaaaaaa-0000-0000-0000-000000000003' where id=(select id from mention_fixture);
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id',null,'unlinked owner has no mention identity');
insert into core.workspaces(id,slug,name) values('22222222-2222-2222-2222-222222222229','mention-isolation','Synthetic mention isolation');
insert into sales.telegram_members(workspace_id,user_id,telegram_user_id) values('22222222-2222-2222-2222-222222222229','aaaaaaaa-0000-0000-0000-000000000003',999);
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id',null,'a verified link in another workspace cannot be mentioned');
update sales.telegram_lead_cards set needs_sync=false,lease_until=now()+interval '2 minutes';
create temporary table prior_token as select token from sales.telegram_lead_cards where lead_id=(select id from mention_fixture);
insert into sales.telegram_members(workspace_id,user_id,telegram_user_id) values('11111111-1111-1111-1111-111111111111','aaaaaaaa-0000-0000-0000-000000000004',444);
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id',null,'another salesperson link never becomes this owner mention');
select ok((select not needs_sync from sales.telegram_lead_cards where lead_id=(select id from mention_fixture)),'unrelated salesperson linking leaves card alone');
insert into sales.telegram_members(workspace_id,user_id,telegram_user_id) values('11111111-1111-1111-1111-111111111111','aaaaaaaa-0000-0000-0000-000000000003',333);
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id','333','current active verified assignee identity is projected as an exact string');
select ok((select needs_sync and lease_until is null and token<>(select token from prior_token) from sales.telegram_lead_cards where lead_id=(select id from mention_fixture)),'link queues existing card and invalidates stale buttons');
update sales.telegram_lead_cards set needs_sync=false;
update sales.telegram_members set linked_at=now() where telegram_user_id=333;
select ok((select not needs_sync from sales.telegram_lead_cards where lead_id=(select id from mention_fixture)),'unchanged identity does not queue redundant edits');
update core.memberships set status='suspended' where workspace_id='11111111-1111-1111-1111-111111111111' and user_id='aaaaaaaa-0000-0000-0000-000000000003';
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id',null,'inactive app membership cannot be mentioned');
update core.memberships set status='active' where workspace_id='11111111-1111-1111-1111-111111111111' and user_id='aaaaaaaa-0000-0000-0000-000000000003';
update sales.telegram_members set telegram_user_id=555 where telegram_user_id=333;
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id','555','relink selects the newly verified identity');
select ok((select needs_sync from sales.telegram_lead_cards where lead_id=(select id from mention_fixture)),'relink queues the existing message');
update sales.telegram_lead_cards set needs_sync=false;
delete from sales.telegram_members where telegram_user_id=555;
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id',null,'unlink removes mention identity');
select ok((select needs_sync from sales.telegram_lead_cards where lead_id=(select id from mention_fixture)),'unlink queues name-only replacement');
select is((select owner_id::text from sales.leads where id=(select id from mention_fixture)),'aaaaaaaa-0000-0000-0000-000000000003','link lifecycle never reassigns the lead');
select is((select status::text from sales.leads where id=(select id from mention_fixture)),'new','link lifecycle never changes customer progress');
update sales.leads set owner_id='aaaaaaaa-0000-0000-0000-000000000004' where id=(select id from mention_fixture);
select is(sales.telegram_card_data((select id from mention_fixture))->>'assignee_telegram_id','444','later assignment uses only the new owner identity');
select ok(not has_function_privilege('authenticated','sales.refresh_telegram_member_cards()','execute'),'refresh trigger is private');
select * from finish();
rollback;
